# Species entries format (id,name,common,biome,kind,role,source,methods,care,monitor,caution,refs,season)
# Kind = native, farm, hold. All field instructions are starting points requiring local extension input.
entries=[]
def add(id,n,c,b,k,role,source,method,care,monitor,caution,refs,season='Local onset of reliable rains; avoid storms and waterlogging.'):
 entries.append(dict(id=id,name=n,common=c,biome=b,kind=k,role=role,source=source,method=method,care=care,monitor=monitor,caution=caution,refs=refs.split(),season=season))
add('symphonia','Symphonia globulifera','Native canopy tree','humid','native','Habitat structure, shade and forest diversity','SNGF or a district-licensed native nursery; request seed-origin record.','Use locally collected, legally sourced nursery stock only in a mapped historical humid-forest restoration plot. Local botanist sets handling and spacing.','Mulch away from stem; protect from fire, trampling and cyclone damage.','Tag seedlings; inspect canopy damage and 12-month survival.','Local range, wetness, taxonomy and provenance require on-site verification.','S2 S12 S34')
add('ravenala','Ravenala madagascariensis','Traveller’s tree','humid','native','Existing eastern-forest mosaic and agroforestry structural diversity','SNGF or local indigenous nursery; verify provenance and site range.','Raise verified nursery seedlings; use only within documented natural range on disturbed humid-forest edges where restoration specialists advise.','Water during establishment if needed; protect from cyclone exposure.','Recruitment, mortality, seed spread and wildlife use.','Do not assume natural range extends to any Madagascar district; avoid mass single-species planting.','S1 S2 S12')
add('intsia','Intsia bijuga','Indian Ocean ironwood','humid','native','Long-lived coastal/littoral forest tree where locally indigenous','SNGF/native community nursery, only site-matched local genotype.','Specialist nursery propagation; restore into verified historical littoral/coastal forest behind appropriate setback.','Protect from salt spray beyond tolerance, encroachment and fires.','Tag growth and canopy recovery at 6 and 12 months.','Slow-growing; may face harvest pressure; jurisdictional protection and provenance check needed.','S2 S12')
add('vanilla','Vanilla planifolia','Vanilla (existing farm crop)','humid','farm','Income diversification under an existing multistory farm canopy','Certified clean cuttings from established local producers/cooperatives; verify phytosanitary health.','Plant healthy cuttings at base of locally approved support trees in existing shaded fields; ensure drainage and expert pruning practice.','Use shade management, mulch, clean tools and sanitation; watch Fusarium root/stem rot.','Vine survival, disease, labor, flowering and net household income.','Non-native commercial crop; no conversion of remaining forest to vanilla plantations.','S18 S19 S35')
add('cacao','Theobroma cacao','Cacao (managed agroforest)','humid','farm','Shade-grown household income on existing farmland','Local nursery or established grower cooperative offering selected disease-free plants.','Use existing cultivated land with layered, preferably native shade; transplant at rainy season with drainage and tested cultivars.','Weed/mulch; monitor shade, black-pod disease, pests and soil fertility.','Fruit yield, tree disease, shade diversity and cost of care.','Do not expand by clearing native forest; not adapted to cool uplands or dry south.','S18 S35')
add('ginger','Zingiber officinale','Ginger (managed garden)','humid','farm','Short-cycle cash/food crop in existing garden land','Existing local agricultural input/cooperative suppliers of disease-free rhizomes.','Plant sound rhizome pieces in prepared raised beds with mulch and rain-fed moisture; agree local spacing with extension agent.','Maintain drainage; remove rotting plants; rotate and avoid contaminated planting stock.','Stand establishment, rot symptoms and harvest volume.','Contain in existing farm boundaries; do not plant in forest understory.','S18 S35')
add('tapia','Uapaca bojeri','Tapia tree','subhumid','native','Native fire-tolerant tapia woodland, edible fruits, wild-silk habitat','SNGF or authorized tapia-conservation nursery, with local genetic provenance.','Only reinforce documented tapia woodland or suitable recovery mosaic under local woodland management, not a blanket tree plantation.','Protect regeneration from recurring destructive fires, livestock browse and harvesting pressure.','Natural seedlings, landibe moth habitat, grazing compatibility and tree survival.','Tapia woodland is an ecosystem with local rights and special management; do not overplant.','S15 S25 S3')
add('podocarpus','Podocarpus madagascariensis','Madagascar podocarp','subhumid','native','Native forest diversity in suitable highland forest remnants','SNGF offers this taxon in its forest seedling listings; confirm exact species and geographic provenance.','Nursery-raised planting only inside appropriate restored native forest, after local range survey.','Protect shade/moisture for young plants; prevent soil disturbance.','12-month survival, natural recruitment and wildlife recovery.','Species-specific forest requirement and protected status require verification.','S4 S12 S2')
add('bean','Phaseolus vulgaris','Common bean (cultivated)','subhumid','farm','Protein and nitrogen contribution within crop rotation','FOFIFA/SOC-accredited crop seed providers, matching altitude and variety.','Sow tested local cultivar in cultivated plots at first reliable rain; follow packet or extension row-depth recommendations.','Weed early; maintain rotation, control bean disease and drain saturated soil.','Germination, pod yield, pests and soil cover.','This is a crop, not a forest-restoration species.','S6 S8')
add('sweetpotato','Ipomoea batatas','Sweet potato (cultivated)','subhumid','farm','Nutrition and field coverage on suitable cultivated land','Disease-free local vine cuttings from agricultural nursery or farmer seed network.','Set cuttings on cultivated ridges or beds once moisture sufficient; choose locally tested cultivar.','Weed, protect cuttings from grazing, manage weevils, ensure adequate establishment moisture.','Tuber harvest, vine survival, weevil damage and dietary use.','Use managed farmland; sweet potato is not appropriate as a habitat restoration introduction.','S6 S8')
add('potato','Solanum tuberosum','Potato (highland farm crop)','subhumid','farm','Cooler-highland calories and livelihood diversification','SOC-authorized supplier or FOFIFA-linked disease-free seed potatoes.','Plant certified tubers into cultivated well-drained highland beds in locally recommended season.','Hill soil, rotate crops and promptly remove blight-infected leaves as advised.','Yield, blight incidence, storage loss and input cost.','Avoid seed potatoes of unknown disease status.','S6 S8')
add('dalbergia','Dalbergia greveana','Madagascar rosewood (dry-forest)','dry','native','Ecological restoration of site-matched dry forests; habitat diversity','SNGF lists this species; obtain legal-origin plants and paperwork directly.','Use local-origin, legally documented nursery plants only as part of native-species mix in verified natural range.','Protect seedlings against fire, grazing and illegal cutting.','Survival and anti-harvest safeguards, with no public precise GPS for rare plants.','High conservation/harvest sensitivity; NEVER trade wild seed or wood without legal clearance.','S4 S16 S22 S30')
add('cordyla','Cordyla madagascariensis','Native western dry-forest tree','dry','native','Canopy diversity in western dry and transitional forest','SNGF/native local nursery; ask district botanist to identify suitable seed stands.','Raise stock from approved local sources; plant into verified historical forest with firebreak and browsing plan.','Establish at rains; mulch where sensible; keep invasive grasses from seedlings.','Annual survival, growth and return of natural vegetation.','Locally verify occurrence and soil before moving planting material between districts.','S16 S22')
add('abrahamia','Abrahamia ditimena','Native seasonally dry-forest tree','dry','native','Local dry forest reconstruction with Malagasy endemic flora','Locally sourced permitted tree nursery; confirm updated taxon name before purchase.','Seed/nursery protocol only after practitioner confirmation; favor assisted natural regeneration if seedlings present.','Exclude damaging fire/grazing; monitor natural recovery.','New native recruits, survival and competitive invasive plants.','Sometimes listed by old name Protorhus ditimena; do not purchase unidentified Protorhus spp.','S26 S2 S12')
add('sorghum','Sorghum bicolor','Sorghum (cultivated)','dry','farm','Drought-tolerant grain crop and household food','SOC-accredited district seller; ask specifically for approved IRAT 204, MACIA or region-registered variety where suitable.','Direct seed into moisture-bearing existing fields following local certified seed packet and soil profile; test small plots first.','Weed in first weeks; control birds and striga where present; avoid water stress at flowering where feasible.','Emergence, days to maturity, grain weight, household consumption and yield per hectare.','A drought-tolerant crop is not drought-proof; regional approval and real water budget still matter.','S7 S9 S6')
add('cowpea','Vigna unguiculata','Cowpea / niébé','dry','farm','Protein, soil cover and crop rotation','SOC-accredited seed producers; Boeny varieties include Black eyes and Zazamena, verify local approval.','For erect cultivars an IITA starting reference is 50 cm between rows × 20 cm plants; adapt locally. Sow 2–3 viable seeds per station, thin per cultivar guidance.','Control early weeds and insects; dry harvested seed well; rotate with cereals.','Germination, pods, dry seed yield, insect damage and dietary use.','Spacing depends on variety (vining types need more space); seed quality and land suitability first.','S9 S14 S6')
add('adansonia_g','Adansonia grandidieri','Grandidier’s baobab','succulent','native','Endemic local-range habitat recovery and long-term genetic conservation','SNGF/approved conservation partners only, with local authorization and provenance.','Only specialist planting within its narrow southwestern coastal dry forest range; prioritize safeguarding adults and natural seedlings.','Establish during adequate rain; protect from grazing, fire and illegal removal.','Existing adults, recruit survival, seed origin and long-term habitat trend.','Not a general drought tree for the rest of Madagascar; endangered/high-conservation-value.','S27 S4 S2')
add('adansonia_za','Adansonia za','Za baobab','succulent','native','Native woodland structure and biodiversity where locally indigenous','SNGF or registered Malagasy endemic-tree nursery; request precise permitted provenance.','Raise approved seedlings only for locales with verified natural occurrence, ideally in mixed native woodland restoration.','Protect saplings from browsing and fire over multiple seasons.','Annual survival, regeneration and fruiting of mature local stock.','Do not mix separate district genetic populations indiscriminately.','S4 S2 S16')
add('bambara','Vigna subterranea','Bambara groundnut / voanjobory','succulent','farm','Resilient grain legume, nutritional diversity','SOC seed producers or local crop cooperative with region-appropriate verified seed.','Sow into prepared existing farmland as rainy season starts; plant spacing and maturity based on local cultivar.','Weed during establishment; avoid waterlogging and rotate crops.','Germination, food availability and grain storage losses.','Suitability of a particular cultivar under very low rain remains unverified until trials.','S6 S8')
add('sesame','Sesamum indicum','Sesame (farm crop)','succulent','farm','Potential low-input cash/food oilseed','SOC-authorized seed dealer if approved variety is documented in district.','Pilot only in an existing well-drained plot during reliable rainfall, subject to local extension guidance.','Keep weed-free early; protect maturing capsules and dry promptly.','Seed yield, disease, market price and labor.','Availability/registration in a given district is not confirmed here.','S6 S32')
add('alluaudia','Alluaudia procera','Octopus tree / native spiny thicket','spiny','native','Structure and habitat continuity in Madagascar’s spiny thicket','Authorized local conservation nursery only; verify Didiereaceae permits and origin.','Do not transplant from the wild; specialist nursery restoration only on verified indigenous spiny-forest sites.','Shield from herbivory and fire, avoid excessive irrigation and disturbance.','12-month survival, recruitment and adjacent endemic flora.','Didiereaceae are regulated; never advertise online wild collection or unscreened trade.','S1 S30 S2')
add('didierea','Didierea madagascariensis','Endemic spiny-thicket tree','spiny','native','Conserve threatened arid thorn-forest habitat','Authorized endemic-species conservation programme and local community nursery.','Conservation-led propagation only after district-level habitat, legal and genetic review.','Prefer protection of naturally regenerating plants; careful establishment irrigation by local expert.','Plant survival and vegetation composition rather than tree-count targets.','Spiny-thicket specialist, protected movement restrictions; not ornamental export project.','S1 S30 S22')
add('moringa_d','Moringa drouhardii','Endemic Malagasy dryland tree','spiny','native','Specialist recovery of southern/southwestern native vegetation','Authorized local native-tree nursery or botanist; confirm natural range.','Pilot with site-matched endemic nursery stock on degraded native habitat only after expert advice.','Exclude livestock pressure, watch for drought mortality in first two seasons.','Survival, wild recruitment and habitat fit.','Do not confuse with introduced Moringa oleifera or assume the same edible uses.','S1 S2 S12')
add('peanut','Arachis hypogaea','Groundnut / arachide','spiny','farm','Food, oil, diversified crop rotation','SOC-approved seed network; Boeny approvals include Marabe, Menakely and Menabe, but confirm southern suitability.','Sow clean, locally recommended seed into soil with reliable early moisture in existing crop plots.','Weed/earth up as advised, dry pods on clean surfaces; avoid mold during storage.','Pods, aflatoxin-prevention practices, household consumption and soil erosion.','Requires rain during establishment; poor drying can cause serious food-safety hazards.','S9 S6 S8')
add('pigeonpea','Cajanus cajan','Pigeon pea / cajanus','spiny','farm','Perennial legume for managed field margins and edible pulses','Regionally established crop-seed producer via SOC directory or FOFIFA partner; confirm allowed variety.','On farm boundaries only: test 1 m between rows, 30–50 cm in-row for a standalone crop and 2.5–4 cm sowing depth as general FAO reference.','Protect seedlings from browse; prune only with local guidance; manage pod pests.','Household harvest, survival and any escape outside field perimeter.','Woody legume with potential to persist/spread; avoid near natural habitat without ecological assessment.','S29 S6 S8')
add('cassava','Manihot esculenta','Cassava (existing cultivated crop)','spiny','farm','Drought-season calories once established in suitable field','Disease-free cuttings from Malagasy approved local crop nursery or farmer network.','Plant viable stakes in existing fields at start of reliable rain; follow local cultivar and spacing advice.','Weed first months; manage mosaic disease; avoid exhausting poor soils.','Yield, root rot, plant health and household cooking protocols.','Some varieties have high cyanogenic compounds: safe processing is essential; never consume raw roots/leaves.','S6 S8')
add('rhizophora','Rhizophora mucronata','Red mangrove','mangrove','native','Tidal mangrove recruitment in locally suitable elevations','Nearby community-run mangrove nursery/approved restoration group; e.g. ADRA MIATRIKA project area.','First re-establish tidal exchange and natural propagule recruitment; plant local propagules only in matched tidal zones when experts determine needed.','Protect tidal channels from blockage and propagules from trampling.','Tidal exposure, sediment level, natural recruits, survival and shoreline change.','Planting into seagrass, tidal mudflats or unsuitable elevations can cause harm and fail.','S13 S17 S24 S31')
add('avicennia','Avicennia marina','Grey mangrove','mangrove','native','Mangrove zone diversity, saline-site recruitment','Existing Madagascar community nursery with local seed provenance.','Ecological hydrology first; restore only in correct local elevation and salinity zone; support natural regeneration if present.','Monitor water flows, avoid cutting channels and grazing.','Recruitment by tidal band and seedling health.','Do not assume tolerance means suitable for every bare coastal flat.','S13 S17 S24')
add('ceriops','Ceriops tagal','Ceriops mangrove','mangrove','native','Tidal-gradient diversity and mangrove recovery','Local coastal nursery linked to local restoration programme, with permission.','Species-specific position on tidal gradient selected by local restoration team; no blanket seedling grids.','Track tidal connectivity, freshwater inflow and propagule survival.','Survival by elevation, creek connection and natural regeneration.','Only in historically mangrove-appropriate sites; protect intertidal non-mangrove habitat.','S13 S17 S24')
add('sonneratia','Sonneratia alba','Mangrove apple','mangrove','native','Mangrove species diversity along suitable coast','Approved local mangrove nursery or community-collected propagules under authorization.','Use only where hydrodynamics and substrate match existing local Sonneratia stands.','Protect estuarine water flows, monitor erosion and water quality.','Presence of natural recruits, seedling survival and fish habitat.','Expert identification important; no mass planting on open tidal flats.','S13 S17')
add('rice','Oryza sativa','Rice (managed paddy crop)','wetland','farm','Staple food in existing rice production systems','FOFIFA certified varieties via SOC-accredited sellers and regional research stations.','Only within legally existing paddy systems; choose locally recommended irrigated or rain-fed variety, seedbed and planting schedule.','Manage irrigation judiciously; protect natural marsh edges, soil and downstream water users.','Grain yield, irrigation volume and wetland boundary integrity.','Never drain natural marshes or clear swamp forest to expand rice.','S8 S6')
add('taro','Colocasia esculenta','Taro (cultivated)','wetland','farm','Diverse starch crop in established moist gardens','Locally produced clean corms/planting pieces with agricultural extension advice.','Plant only in already-cultivated moist plots with controlled water, separate from native marshes.','Manage pests and water; cook edible parts properly, monitor wetland escape.','Plant yield, flood damage and native wetland vegetation.','Can spread or escape in wet places; raw taro is irritating/toxic and requires proper cooking.','S6 S2')
add('marsh_native','Native sedges & riparian assemblages (locally identified)','Botanist-approved native guild','wetland','hold','Protect soil, wetland bird habitat, filtration and water retention','Local wetland plant conservation nursery after species-specific identification and authorization.','Protect wetland hydrology and natural colonisation; plant only named, surveyed local species where required.','Remove invasive water hyacinth by approved programmes; reduce grazing/contamination.','Native plant cover, wetland water levels, invasive cover and water quality.','Not a retail species: avoid importing foreign sedge or reed mixes.','S2 S12 S21')
add('native_grass','Locally native grasses and forbs','Site survey, not purchased grass mix','grassland','hold','Protect ancient grassland biodiversity, grazing and belowground carbon','Local botany teams and pastoral communities; do not order generic imported grass seed.','Survey grassland origin, indigenous species and pastoral rights before any intervention; support natural grass recovery where degraded.','Reduce damaging erosion/fire pressures as locally agreed; retain necessary grazing access.','Native cover, soil stability, infiltration and livestock access.','Tree planting can damage ancient grassland ecosystems.','S3 S33 S2')
add('ericoid','Local Erica / Helichrysum communities','High-elevation specialists','montane','hold','Conserve rare upland vegetation and watershed function','No consumer purchase recommended; specialists and protected-area managers only.','No planting campaign until native species, microhabitat and climate exposure are surveyed.','Limit trampling, fire, invasive plants and erosion.','Vegetation transects, soil disturbance and species composition.','High-elevation species cannot be generalized across massifs.','S1 S2 S3')
assert len({e['id'] for e in entries})==len(entries)
(P/'species_catalog.json').write_text(json.dumps({'schema_version':1,'reviewed':'2026-10-27','species':entries},indent=2,ensure_ascii=False),encoding='utf-8')

# Build static species cards for offline/no-JS use. Filtering is enhancement only.
def esc(v):return html.escape(str(v),quote=True)
def cite(refs):return ' '.join(f'<a href="#{esc(k)}" class="smallref">[{esc(k)}]</a>' for k in refs)
def href_for(e):
 if e['kind']=='native': return 'https://www.environnement.mg/organisme-rattache/silo-national-des-graines-forestieres-a-madagascar/'
 if e['kind']=='farm': return 'https://soc-semences.miasa.gov.mg/'
 return 'https://mobot.mg/conservation/ecological_restoration/'
card=[]
for e in entries:
 status={'native':'Native restoration candidate','farm':'Established crop · farm only','hold':'Survey / conservation first'}[e['kind']]
 card.append(f'''<article class="species-card" id="plant-{esc(e['id'])}" data-id="{esc(e['id'])}" data-biome="{esc(e['biome'])}" data-kind="{esc(e['kind'])}" data-search="{esc(' '.join([e['name'],e['common'],e['role'],e['biome']]).lower())}">
 <header class="species-head"><div><p class="eyebrow">{esc(dict(biomes).get(e['biome']) if False else next(b[1] for b in biomes if b[0]==e['biome']))}</p><h3><i>{esc(e['name'])}</i></h3><p>{esc(e['common'])}</p></div><span class="tag {esc(e['kind'])}">{esc(status)}</span></header>
 <p class="purpose">{esc(e['role'])}</p>
 <details><summary>Planting, sourcing & 12-month care <span aria-hidden="true">＋</span></summary><div class="detail-content">
 <h4>Source / where to buy or obtain</h4><p>{esc(e['source'])} <a href="{esc(href_for(e))}" target="_blank" rel="noopener noreferrer">Start with verified institutions ↗</a></p>
 <h4>When & how to establish</h4><p>{esc(e['season'])} {esc(e['method'])}</p>
 <h4>Ongoing care</h4><p>{esc(e['care'])}</p><h4>Monitor</h4><p>{esc(e['monitor'])}</p>
 <div class="caution"><strong>Check before acting:</strong> {esc(e['caution'])}</div>
 <p class="mini">Research trail: {cite(e['refs'])}. These are advisory profiles, not permits or guaranteed local suitability.</p>
 </div></details><div class="species-actions"><button type="button" class="tinybtn" data-add="{esc(e['id'])}">＋ Add to local shortlist</button><a href="#fieldbook">Record results</a></div></article>''')
biome_details=[]
for id,name,region,environment,goal in biomes:
 biome_details.append(f'''<article class="biome-tile" id="biome-{id}"><div class="biome-sign"><span>◈</span><span>{esc(id.upper())}</span></div><h3>{esc(name)}</h3><p><b>Where:</b> {esc(region)}</p><p><b>Local conditions:</b> {esc(environment)}</p><p><b>Best approach:</b> {esc(goal)}</p><a href="#catalog" data-pickbiome="{id}">View matching plant profiles ↗</a></article>''')

